// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _test(uint256 setVal, uint256 collectAmt, uint256 lockTime) internal {
        vm.assume(setVal > 0 && collectAmt <= setVal);
        try c.SetMinSum(setVal) {} catch { return; }
        try c.Initialized() {} catch { return; }
        assertTrue(c.MinSum() == setVal);
    }

    function testFuzz_test(uint256 setVal, uint256 collectAmt, uint256 lockTime) public {
        _test(setVal, collectAmt, lockTime);
    }

    receive() external payable {}
}
